// Push gate. Promo rules: max 3 per customer per local calendar day,
// and at least 2 hours between two promos to the same customer.
// Security pushes are transactional: always allowed, never counted.

const MAX_PROMOS_PER_DAY = 3;
const MIN_GAP_MS = 2 * 60 * 60 * 1000;
// A local day is at most 25 hours long, so older sends can never matter.
const KEEP_MS = 48 * 60 * 60 * 1000;

const formatters = new Map();

// Calendar date of `ms` in `timeZone`, as "YYYY-MM-DD". Throws RangeError on a bad zone.
function localDay(ms, timeZone) {
  let fmt = formatters.get(timeZone);
  if (!fmt) {
    fmt = new Intl.DateTimeFormat('en-US', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    });
    formatters.set(timeZone, fmt);
  }
  let y = '', m = '', d = '';
  for (const p of fmt.formatToParts(ms)) {
    if (p.type === 'year') y = p.value;
    else if (p.type === 'month') m = p.value;
    else if (p.type === 'day') d = p.value;
  }
  return `${y}-${m}-${d}`;
}

export function createGate() {
  const promosByUser = new Map(); // userId -> [{ id, t }]
  const promoById = new Map(); // id -> { userId, t }
  let seq = 0;

  const newId = (prefix) => `${prefix}-${++seq}`;

  function prune(userId, list, nowMs) {
    const kept = [];
    for (const rec of list) {
      if (nowMs - rec.t > KEEP_MS) promoById.delete(rec.id);
      else kept.push(rec);
    }
    if (kept.length === 0) promosByUser.delete(userId);
    else promosByUser.set(userId, kept);
    return kept;
  }

  function request({ userId, timeZone, category, now } = {}) {
    if (category === 'security') {
      return { allowed: true, rule: '', id: newId('sec') };
    }
    if (category !== 'promo') {
      return { allowed: false, rule: 'invalid-category', id: null };
    }
    const nowMs = now instanceof Date ? now.getTime() : NaN;
    if (Number.isNaN(nowMs)) {
      return { allowed: false, rule: 'invalid-time', id: null };
    }
    let today;
    try {
      today = localDay(nowMs, timeZone);
    } catch {
      return { allowed: false, rule: 'invalid-time-zone', id: null };
    }

    const list = prune(userId, promosByUser.get(userId) ?? [], nowMs);

    for (const rec of list) {
      if (Math.abs(nowMs - rec.t) < MIN_GAP_MS) {
        return { allowed: false, rule: 'min-gap', id: null };
      }
    }
    let count = 0;
    for (const rec of list) {
      if (localDay(rec.t, timeZone) === today) count++;
    }
    if (count >= MAX_PROMOS_PER_DAY) {
      return { allowed: false, rule: 'daily-cap', id: null };
    }

    // Allowed: caller sends now, so record it now.
    const id = newId('promo');
    const rec = { id, t: nowMs };
    list.push(rec);
    promosByUser.set(userId, list);
    promoById.set(id, { userId });
    return { allowed: true, rule: '', id };
  }

  function cancel(id) {
    const info = promoById.get(id);
    if (!info) return; // unknown, security, pruned, or already cancelled
    promoById.delete(id);
    const list = promosByUser.get(info.userId);
    if (!list) return;
    const kept = list.filter((rec) => rec.id !== id);
    if (kept.length === 0) promosByUser.delete(info.userId);
    else promosByUser.set(info.userId, kept);
  }

  return { request, cancel };
}

import assert from 'node:assert/strict';
import { createGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/baseline-d2-3/bot.mjs';

const LA = 'America/Los_Angeles', BER = 'Europe/Berlin';
const req = (g, o) => g.request({ userId: 'u', timeZone: LA, category: 'promo', ...o });
const at = (s) => new Date(s);

// cap 3 per day, gap 2h
let g = createGate();
assert.equal(req(g, { now: at('2026-03-10T17:00:00Z') }).allowed, true);
assert.equal(req(g, { now: at('2026-03-10T18:59:59Z') }).rule, 'min-gap');
assert.equal(req(g, { now: at('2026-03-10T19:00:00Z') }).allowed, true);
assert.equal(req(g, { now: at('2026-03-10T21:00:00Z') }).allowed, true);
assert.equal(req(g, { now: at('2026-03-10T23:00:00Z') }).rule, 'daily-cap');
// security unaffected, and not counted
assert.equal(g.request({ userId: 'u', timeZone: LA, category: 'security', now: at('2026-03-10T21:01:00Z') }).allowed, true);
// next LA midnight (07:00Z on 03-11, after DST start 03-08 => PDT, UTC-7)
assert.equal(req(g, { now: at('2026-03-11T06:59:00Z') }).rule, 'daily-cap');
assert.equal(req(g, { now: at('2026-03-11T07:00:00Z') }).allowed, true);

// other user independent
assert.equal(g.request({ userId: 'v', timeZone: LA, category: 'promo', now: at('2026-03-10T17:00:00Z') }).allowed, true);

// Berlin: midnight is 23:00Z in winter
g = createGate();
const b = (s) => req(g, { timeZone: BER, now: at(s) });
assert.ok(b('2026-01-10T08:00:00Z').allowed);
assert.ok(b('2026-01-10T10:00:00Z').allowed);
assert.ok(b('2026-01-10T22:00:00Z').allowed); // 23:00 local
assert.ok(b('2026-01-11T00:30:00Z').allowed); // 01:30 local, new day

// cancel frees cap and gap; double cancel / unknown harmless
g = createGate();
const a1 = req(g, { now: at('2026-03-10T17:00:00Z') });
assert.equal(req(g, { now: at('2026-03-10T17:30:00Z') }).rule, 'min-gap');
g.cancel(a1.id); g.cancel(a1.id); g.cancel('nope'); g.cancel(undefined);
assert.ok(req(g, { now: at('2026-03-10T17:30:00Z') }).allowed);
const c1 = req(g, { now: at('2026-03-10T20:00:00Z') });
const c2 = req(g, { now: at('2026-03-10T22:00:00Z') });
assert.equal(req(g, { now: at('2026-03-10T23:59:00Z') }).rule, 'daily-cap');
g.cancel(c2.id);
assert.ok(req(g, { now: at('2026-03-10T23:59:00Z') }).allowed);

// bad inputs
assert.equal(req(g, { timeZone: 'Mars/Base', now: at('2026-03-10T17:00:00Z') }).allowed, false);
assert.equal(g.request({ userId: 'u', timeZone: 'Mars/Base', category: 'security', now: new Date() }).allowed, true);
console.log('ok');
